#!/usr/bin/env python3
import json
from pathlib import Path

import pandas as pd
import pyarrow as pa
import pyarrow.parquet as pq

SOURCES = {
    "source_a": Path("/data/source_a/users.json"),
    "source_b": Path("/data/source_b/users.csv"),
    "source_c": Path("/data/source_c/users.parquet"),
}
FIELDS = ["user_id", "name", "email", "created_date", "status"]
CONFLICT_FIELDS = ["name", "email", "created_date", "status"]

ALIASES = {
    "user_id": ["user_id", "id", "userId"],
    "email": ["email", "email_address"],
    "name": ["full_name", "name", "userName"],
    "created_date": ["registration_date", "created_at", "joined"],
    "status": ["status", "is_active", "active"],
}

def is_missing(v):
    if v is None:
        return True
    try:
        if pd.isna(v):
            return True
    except (TypeError, ValueError):
        pass
    return False

def norm_key(k):
    return str(k).strip().lower().replace("_", "").replace("-", "")

ALIAS_NORM = {
    field: {norm_key(a) for a in aliases}
    for field, aliases in ALIASES.items()
}

def find_value(row, field):
    for alias in ALIASES[field]:
        if alias in row and not is_missing(row[alias]):
            return row[alias]
    for col, value in row.items():
        if norm_key(col) in ALIAS_NORM[field] and not is_missing(value):
            return value
    return None

def as_text(value):
    if is_missing(value):
        return None
    text = str(value).strip()
    return text or None

def normalize_user_id(value):
    if is_missing(value):
        return None
    try:
        number = pd.to_numeric(value, errors="coerce")
        if pd.isna(number):
            return None
        return int(number)
    except (TypeError, ValueError, OverflowError):
        return None

def normalize_date(value):
    if is_missing(value):
        return None
    text = as_text(value)
    try:
        dt = pd.to_datetime(text, errors="coerce")
        if pd.isna(dt):
            return None
        return dt.strftime("%Y-%m-%d")
    except (TypeError, ValueError):
        return None

def normalize_status(value):
    if is_missing(value):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    text = as_text(value).lower()
    if text in {"true", "1", "yes", "y", "active", "enabled"}:
        return "active"
    if text in {"false", "0", "no", "n", "inactive", "disabled"}:
        return "inactive"
    return text

NORMALIZERS = {
    "user_id": normalize_user_id,
    "name": as_text,
    "email": as_text,
    "created_date": normalize_date,
    "status": normalize_status,
}

def normalize_record(row):
    rec = {}
    for field in FIELDS:
        rec[field] = NORMALIZERS[field](find_value(row, field))
    return rec
