    if isinstance(data, dict):
        for key in ("users", "records", "data"):
            if isinstance(data.get(key), list):
                data = data[key]
                break
    if not isinstance(data, list):
        raise ValueError("source_a JSON must be a list of records")
    return [normalize_record(r) for r in data if isinstance(r, dict)]


def read_source_b():
    df = pd.read_csv(SOURCES["source_b"], dtype=str)
    return [normalize_record(r) for r in df.to_dict("records")]


def read_source_c():
    df = pd.read_parquet(SOURCES["source_c"])
    return [normalize_record(r) for r in df.to_dict("records")]
