def merge_sources(records_by_source):
    users = {}
    for source in SOURCES:
        for rec in records_by_source[source]:
            uid = rec.get("user_id")
            if uid is None:
                continue
            users.setdefault(uid, {})
            # First record in a source wins if duplicate IDs occur within that source.
            users[uid].setdefault(source, rec)

    merged_rows = []
    conflicts = []
    for uid in sorted(users):
        source_records = users[uid]
        row = {"user_id": uid}
        for field in FIELDS[1:]:
            row[field] = None
            for source in SOURCES:
                value = source_records.get(source, {}).get(field)
                if not is_missing(value):
                    row[field] = value
                    break
        merged_rows.append(row)

        for field in CONFLICT_FIELDS:
            values = {
                source: source_records[source][field]
                for source in SOURCES
                if source in source_records and not is_missing(source_records[source].get(field))
            }
            # Compare normalized semantic values, not different raw spellings
            # such as "true"/True/"active".
            if len({json.dumps(v, sort_keys=True, ensure_ascii=False) for v in values.values()}) > 1:
                selected = None
                for source in SOURCES:
                    if source in values:
                        selected = values[source]
                        break
                conflicts.append({
                    "user_id": uid,
                    "field": field,
                    "values": values,
                    "selected": selected,
                })

    return merged_rows, conflicts


def write_outputs(merged_rows, conflicts):
    schema = pa.schema([
        pa.field("user_id", pa.int64()),
        pa.field("name", pa.string()),
        pa.field("email", pa.string()),
        pa.field("created_date", pa.string()),
        pa.field("status", pa.string()),
    ])
    df = pd.DataFrame(merged_rows, columns=FIELDS)
    df["user_id"] = df["user_id"].astype("int64")
    table = pa.Table.from_pandas(df, schema=schema, preserve_index=False)
    pq.write_table(table, "/app/merged_users.parquet")

    report = {
        "total_conflicts": len(conflicts),
        "conflicts": conflicts,
    }
    with open("/app/conflicts.json", "w", encoding="utf-8") as f:
        json.dump(report, f, indent=2, ensure_ascii=False)
        f.write("\n")


def main():
    records_by_source = {
        "source_a": read_source_a(),
        "source_b": read_source_b(),
        "source_c": read_source_c(),
    }
    merged_rows, conflicts = merge_sources(records_by_source)
    write_outputs(merged_rows, conflicts)
    print(f"Wrote {len(merged_rows)} users and {len(conflicts)} conflicts")


if __name__ == "__main__":
    main()
